using System.IO.Compression;
using System.Text.Json;
using System.Net;
using TextText.Core;
static class Worker
{
    const string Account="fixture-owner",Workspace="contract-workspace";static readonly Uri VirtualOrigin=new("https://folder-fixture.invalid/");
    [System.Runtime.InteropServices.DllImport("kernel32.dll",CharSet=System.Runtime.InteropServices.CharSet.Unicode,SetLastError=true)]static extern bool MoveFileW(string source,string destination);
    static string FolderIdentity(string path)=>(string)typeof(TextPackStore).Assembly.GetType("TextText.Core.FolderCaseRename")!.GetMethod("Identity",System.Reflection.BindingFlags.Static|System.Reflection.BindingFlags.NonPublic,null,[typeof(string)],null)!.Invoke(null,[path])!;
    static readonly JsonSerializerOptions Json=new(){PropertyNamingPolicy=JsonNamingPolicy.CamelCase,PropertyNameCaseInsensitive=true};
    sealed class FixedEndpoint(Uri actual):DelegatingHandler(new HttpClientHandler{AllowAutoRedirect=false}){
        protected override Task<HttpResponseMessage> SendAsync(HttpRequestMessage request,CancellationToken ct){var uri=request.RequestUri!;if(uri.Scheme!="https"||uri.Host!=VirtualOrigin.Host||uri.Port!=443)throw new IOException("Fixture refuses unexpected virtual origin.");request.RequestUri=new Uri(actual,uri.PathAndQuery);return base.SendAsync(request,ct);}
    }
    static void Check(bool ok,string message){if(!ok)throw new Exception(message);}
    static SyncEngine.State State(TextPackStore store)=>JsonSerializer.Deserialize<SyncEngine.State>(File.ReadAllBytes(Path.Combine(store.StateDirectory,"sync.json")))!;
    static string Identity(byte[] bytes)=>TextPackStore.Hash(bytes);
    static async Task Main(string[] args)
    {
        Check(args.Length==4,"Pass mode, owned scratch, nonce and ready origin.");var mode=args[0];var scratch=Path.GetFullPath(args[1]);Check(File.ReadAllText(Path.Combine(scratch,"fixture-nonce"))==args[2],"Owned fixture nonce mismatch.");var actual=new Uri(args[3]);Check(actual.Scheme=="http"&&actual.Host==(Environment.GetEnvironmentVariable("TEXTTEXT_FIXTURE_EXPECTED_HOST")??"127.0.0.1")&&actual.Port>1024&&actual.AbsolutePath=="/"&&actual.UserInfo==""&&actual.Query=="","Only the explicitly pinned owned fixture address is allowed.");
        using var client=new HttpClient(new FixedEndpoint(actual)){Timeout=TimeSpan.FromSeconds(15)};
        var tokenFile=Path.Combine(scratch,"fixture-token");var fixtureToken=File.Exists(tokenFile)?File.ReadAllText(tokenFile):"vault-http-fixture";
        var transport=new HttpSyncTransport(client,VirtualOrigin,Workspace,Account,()=>Task.FromResult(new SyncAccountCredential(fixtureToken,Account)));
        var bytes=File.ReadAllBytes(Path.Combine(scratch,"archive.textpack"));var hash=Identity(bytes);const string id="folder-http-item";var lower="Parent/Case/one.textpack";var upper="Parent/CASE/one.textpack";
        string RequestPath(string label)=>Path.Combine(scratch,label+"-command.json");
        if(mode.StartsWith("wire-",StringComparison.Ordinal)){
            if(mode=="wire-seed"){await transport.UploadAsync(id,lower,bytes,null,Guid.NewGuid().ToString("D"));var manifest=await transport.ManifestAsync();Check(transport.SupportsFolderCaseMoves&&transport.ManifestRevision is not null,"Explicit fixture capability missing.");var request=new FolderCaseMoveRequest(Guid.NewGuid().ToString("D"),"Parent/Case","Parent/CASE",transport.ManifestRevision!,transport.Folders.Where(p=>p=="Parent/Case"||p.StartsWith("Parent/Case/",StringComparison.Ordinal)).ToArray(),manifest.Select(x=>new FolderCaseMoveItem(x.ItemId,x.RelativePath,x.Revision)).ToArray());File.WriteAllBytes(RequestPath("wire"),JsonSerializer.SerializeToUtf8Bytes(request,Json));Console.WriteLine("RESULT "+JsonSerializer.Serialize(new{mode,qualification="production HTTP transport only; no Windows observer",request.OperationId,hash},Json));return;}
            var retained=JsonSerializer.Deserialize<FolderCaseMoveRequest>(File.ReadAllBytes(RequestPath("wire")),Json)!;
            if(mode=="wire-lost"){var lost=false;try{await transport.MoveFolderCaseAsync(retained);}catch(HttpRequestException){lost=true;}Check(lost,"Owned fixture did not lose committed reply.");Console.WriteLine("RESULT "+JsonSerializer.Serialize(new{mode,qualification="production HTTP transport only; harness command retained",retained.OperationId,hash},Json));return;}
            if(mode=="wire-resume"){var receipt=await transport.MoveFolderCaseAsync(retained);var pack=await transport.DownloadAsync(id);Check(receipt.OperationId==retained.OperationId&&receipt.Folders.Contains("Parent/CASE/Empty child")&&pack.RelativePath==upper&&pack.Data.SequenceEqual(bytes),"Real wire replay changed full archive or empty subtree.");var inspect=await transport.RecoverFolderCaseAsync(retained,false,null);Check(inspect.State=="completed"&&inspect.Result?.OperationId==retained.OperationId,"Real server did not return authoritative completed proof.");Console.WriteLine("RESULT "+JsonSerializer.Serialize(new{mode,qualification="production HTTP transport replay; no Windows observer",retained.OperationId,hash,receipt},Json));return;}
            throw new Exception("Unknown wire fixture mode.");
        }
        Check(OperatingSystem.IsWindows(),"Full observer/outbox proof requires actual Windows; use wire mode elsewhere.");
        var role=mode.StartsWith("b-",StringComparison.Ordinal)?"b":"a";var store=new TextPackStore(Path.Combine(scratch,"native-"+role),Path.Combine(scratch,"state-"+role));AccountRootOwnership.Open(store,VirtualOrigin,Workspace,Account);var engine=new SyncEngine(store,transport,Account,NativePolicyTestHost.Create(Account));
        if(mode.StartsWith("filesystem-",StringComparison.Ordinal)){
            var from=mode=="filesystem-upper"?"Case":mode=="filesystem-lower"?"CASE":"cASE";var to=mode=="filesystem-upper"?"CASE":mode=="filesystem-lower"?"cASE":"CASE";var source=store.Resolve("Parent/"+from);var target=store.Resolve("Parent/"+to);Check(Directory.EnumerateFileSystemEntries(source).Select(Path.GetFileName).Order(StringComparer.Ordinal).SequenceEqual(new[]{"Empty child","one.textpack"})&&Directory.EnumerateFileSystemEntries(Path.Combine(source,"Empty child")).Count()==0&&File.ReadAllBytes(Path.Combine(source,"one.textpack")).SequenceEqual(bytes),"Filesystem action refuses nonfixture tree.");var before=FolderIdentity(source);Check(MoveFileW(source,target),"Owned ordinary filesystem rename failed.");Check(FolderIdentity(target)==before&&Directory.EnumerateDirectories(store.Resolve("Parent")).Select(Path.GetFileName).SequenceEqual(new[]{to}),"Filesystem action changed directory identity/spelling unexpectedly.");Console.WriteLine("RESULT "+JsonSerializer.Serialize(new{mode,role,actionId=Guid.NewGuid().ToString("D"),from,to,directoryIdentity=before,hash,qualification="ordinary OS directory rename; no product mutation API"},Json));return;
        }
        if(mode=="a-seed"){store.EnsureFolders(["Parent/Case/Empty child"]);store.Write(lower,bytes);await engine.SyncAsync();await engine.SyncAsync();Check(State(store).FolderBaseline?.Items.Single().ItemId==id,"Production folder baseline was not retained.");}
        else if(mode=="b-seed"){await engine.SyncAsync();Check(store.Read(lower).SequenceEqual(bytes),"Second native participant changed seeded archive.");}
        else if(mode is "a-lost" or "a-race"){
            var failed=false;try{await engine.SyncAsync();}catch(Exception e)when(e is HttpRequestException or SyncConflictException){failed=true;}var pending=State(store).FolderCommand;Check(failed&&pending is not null,"Expected native durable command after actual failed HTTP operation.");File.WriteAllBytes(RequestPath(mode=="a-lost"?"native-lost":"native-race"),JsonSerializer.SerializeToUtf8Bytes(pending!.Request,Json));Check(File.ReadAllBytes(store.Resolve(mode=="a-lost"?upper:"Parent/cASE/one.textpack")).SequenceEqual(bytes),"Pending command changed exact local archive.");Console.WriteLine("RESULT "+JsonSerializer.Serialize(new{mode,role,qualification="actual Windows production observer/outbox",pending.Request.OperationId,hash,stateHash=Identity(File.ReadAllBytes(Path.Combine(store.StateDirectory,"sync.json")))},Json));return;
        }
        else if(mode=="a-resume"){
            var retained=File.ReadAllBytes(RequestPath("native-lost"));var before=State(store).FolderCommand!;Check(JsonSerializer.SerializeToUtf8Bytes(before.Request,Json).SequenceEqual(retained),"Restart changed retained operation.");await engine.SyncAsync();Check(State(store).FolderCommand is null&&store.Read(upper).SequenceEqual(bytes),"Restart did not adopt exact whole-folder receipt.");
        }
        else if(mode=="a-cancel"){
            var retained=File.ReadAllBytes(RequestPath("native-race"));var row=await engine.FolderMoveRecoveryReadAsync();Check(row?.State=="review"&&JsonSerializer.SerializeToUtf8Bytes(row.Command,Json).SequenceEqual(retained),"Real server review was not bound to retained original command.");await engine.ResolveFolderMoveRecoveryAsync(row!.Id,row.Inspection,row.LocalInspection,row.RequestHash!);Check(State(store).FolderCommand is null&&File.Exists(Path.Combine(store.StateDirectory,"folder-sync-cancellations",row.Id+".json"))&&store.Read("Parent/cASE/one.textpack").SequenceEqual(bytes),"Authoritative cancellation did not preserve exact local tree and proof.");Console.WriteLine("RESULT "+JsonSerializer.Serialize(new{mode,role,qualification="actual Windows Core authoritative cancellation",row.Id,hash},Json));return;
        }
        else if(mode=="a-replay-cancelled"){var retained=JsonSerializer.Deserialize<FolderCaseMoveRequest>(File.ReadAllBytes(RequestPath("native-race")),Json)!;var refused=false;try{await transport.MoveFolderCaseAsync(retained);}catch(SyncConflictException){refused=true;}Check(refused,"Server cancellation tombstone allowed original publication.");}
        else if(mode is "a-idle" or "b-idle" or "b-converge" or "a-restored"){await engine.SyncAsync();Check(store.Read(upper).SequenceEqual(bytes),"Native convergence/idle changed full archive.");}
        else throw new Exception("Unknown native fixture mode.");
        var scan=store.Scan();Check(scan.Count==1&&scan[0].ItemId==id,"Native participant lost or duplicated stable identity.");using(var archive=new ZipArchive(new MemoryStream(store.Read(scan[0].Path)),ZipArchiveMode.Read)){using var asset=archive.Entries.Single(e=>e.FullName.EndsWith("/assets/exact.bin",StringComparison.Ordinal)).Open();using var saved=new MemoryStream();asset.CopyTo(saved);Check(saved.ToArray().SequenceEqual(new byte[]{0,255,7,19}),"Native participant changed attachment bytes.");}
        Console.WriteLine("RESULT "+JsonSerializer.Serialize(new{mode,role,qualification="actual Windows production Core",itemId=scan[0].ItemId,path=scan[0].Path,hash=scan[0].Hash,folders=State(store).ManagedFolders,directoryIdentity=FolderIdentity(store.Resolve("Parent/"+scan[0].Path.Split('/')[1])),actualFolder=Directory.EnumerateDirectories(store.Resolve("Parent")).Select(Path.GetFileName).Single(),pending=State(store).FolderCommand is not null},Json));
    }
}
